from datetime import datetime, date
import math

# assume venmo_token, start already defined in previous runs

start_date = date(datetime.now().year, 3, 1)

all_friends = []
page_index = 0
page_limit = None

while True:
    if page_limit is None:
        res = apis.venmo.search_friends(access_token=venmo_token, page_index=page_index)
    else:
        res = apis.venmo.search_friends(access_token=venmo_token, page_index=page_index, page_limit=page_limit)
    # res expected list
    print('page', page_index, 'len', len(res))
    if not res:
        break
    all_friends.extend(res)
    page_index += 1

print('total_friends', len(all_friends))

# Parse friends_since and count since start_date

def parse_dt(s):
    if s is None:
        return None
    # try isoformat
    try:
        return datetime.fromisoformat(s.replace('Z','+00:00'))
    except Exception:
        # try date only
        try:
            return datetime.strptime(s[:10], '%Y-%m-%d')
        except Exception:
            return None

since_count = 0
since_list = []
for f in all_friends:
    dt = parse_dt(f.get('friends_since'))
    if dt is None:
        continue
    if dt.date() >= start_date:
        since_count += 1
        since_list.append((f.get('first_name'), f.get('last_name'), f.get('email'), f.get('friends_since')))

print('start_date', start_date)
print('since_count', since_count)
print('sample_since', since_list[:10])

